import 'package:flutter/material.dart';\nimport '../models/ai_tool.dart';\nimport '../services/firebase_service.dart';\nimport '../services/local_storage_service.dart';\n\nclass FavoritesProvider with ChangeNotifier {\n  final FirebaseService _firebaseService = FirebaseService();\n  final LocalStorageService _localStorage = LocalStorageService();\n\n  List<String> _favoriteIds = [];\n  Map<String, AITool> _favoritesCache = {};\n  bool _isLoading = false;\n\n  List<String> get favoriteIds => _favoriteIds;\n  List<AITool> get favorites => _favoritesCache.values.toList();\n  bool get isLoading => _isLoading;\n\n  Future<void> loadFavorites(List<String> ids) async {\n    _isLoading = true;\n    notifyListeners();\n\n    _favoriteIds = ids;\n    _favoritesCache.clear();\n\n    for (final id in ids) {\n      final tool = await _firebaseService.getToolById(id);\n      if (tool != null) {\n        _favoritesCache[id] = tool;\n      }\n    }\n\n    _isLoading = false;\n    notifyListeners();\n  }\n\n  Future<void> addFavorite(String userId, AITool tool) async {\n    if (!_favoriteIds.contains(tool.id)) {\n      _favoriteIds.add(tool.id);\n      _favoritesCache[tool.id] = tool;\n\n      await _localStorage.saveFavorite(tool.id);\n      await _firebaseService.addFavorite(userId, tool.id);\n\n      notifyListeners();\n    }\n  }\n\n  Future<void> removeFavorite(String userId, String toolId) async {\n    _favoriteIds.remove(toolId);\n    _favoritesCache.remove(toolId);\n\n    await _localStorage.removeFavorite(toolId);\n    await _firebaseService.removeFavorite(userId, toolId);\n\n    notifyListeners();\n  }\n\n  bool isFavorite(String toolId) {\n    return _favoriteIds.contains(toolId);\n  }\n}\n